-- BILLAR EL BRUJO V33 - STOCK TXT POR PAQUETES
-- Formula: stock_actual = cantidad del TXT * unidades_por_entrada
-- Antes de ejecutar, configure unidades_por_entrada para cada producto.
SET @SUCURSAL_ID = 1;
START TRANSACTION;

UPDATE productos SET stock_actual = 9 * GREATEST(COALESCE(unidades_por_entrada,1),1), tipo_entrada = CASE WHEN GREATEST(COALESCE(unidades_por_entrada,1),1) > 1 THEN 'PAQUETE' ELSE tipo_entrada END WHERE sucursal_id=@SUCURSAL_ID AND estado='ACTIVO' AND UPPER(TRIM(nombre)) IN (UPPER(TRIM('AGUA 2 LITROS')), UPPER(TRIM('AGUA 2L')));
